let s=fresh();try{const v=JSON.parse(localStorage.getItem('cyper-save'));if(v?.version===1&&Array.isArray(v.inventory)&&maps.some(m=>m.id===v.map))s=v;}catch{}
let world=null,lastSeenChat=0,lastSeenGuild=0,chatMode='global',chatDrafts={},mailDraft='',mailRecipient='',replyId=null,attached=false,attachedGear='',profileSection='profile',activeBadgeSlot=null,selectedMilestone=null;
const sounds=createAudio();
let settingsDraft=null,settingsReturn='hub',pendingDelete=null,victoryModal=null,lastVictory=null,uiBoot=false,clientNotice='';
let marketSection='browse',marketQuery='',marketSlot='all',marketSort='newest',marketDraft={id:'',price:'100'},marketRendered='';
let craftCategory='all',hideUnavailable=false,inboxPage=0,railStation=null;
let bagSection='items',bagSort='power',bagSelected=new Set(),publicProfile=null;
let tab='hub',search='',filter='all',notice='',online=null,players=[],busy=false,selectedGear=null,inventoryTab='equipped',shopTab='buy',catalogPage=0,calibrationId=null,stationOptions={boost:false,protect:false},financeAmount=1;
async function request(url,body){const res=await fetch(url,body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{});const data=await res.json();if(!res.ok)throw new Error(data.error);return data;}
async function refreshWorld(){const previous=world;world=await request('/api/world');watchWorld(previous,world);if(tab==='chat'&&chatMode==='guild')lastSeenGuild=world.guildMessages.at(-1)?.time||lastSeenGuild;if(tab==='chat'&&chatMode==='global')lastSeenChat=world.messages.at(-1)?.time||lastSeenChat;}
async function refreshPlayers(){players=(await request('/api/rank')).players;}
const esc=t=>String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(label,action,id='',disabled=false)=>`<button data-action="${action}" data-id="${id}" ${disabled?'disabled':''}>${uiLabel(label,settings(s).language)}</button>`;
const tabs=[['hub','⌖','Trung tâm'],['map','⌖','Bản đồ'],['rail','♧','Ga tàu'],['dungeon','▥','Dungeon'],['inventory','▣','Trang bị'],['missions','≡','Nhiệm vụ'],['chat','▱','Trò chuyện'],['reputation','♙','Uy tín'],['cores','⬡','Lõi AI'],['bazaar','▥','Khu chợ'],['market','▥','Chợ người chơi'],['alley','◇','Hẻm thông tin'],['pets','♧','Neon Paws'],['tavern','♧','Partyline'],['coast','≈','Bờ biển'],['shop','₡','Cửa hàng'],['black','◉','Chợ đen'],['station','⚒','Hiệu chuẩn'],['printer','▣','Máy in'],['bank','▥','Ngân hàng'],['exchange','◇','Đổi Unit'],['terminal','◈','Terminal'],['commercial','◷','Khu thương mại'],['corporation','♙','Tập đoàn'],['headquarters','♙','Trụ sở'],['housing','▦','Căn hộ'],['cosmetics','◈','Cyberwear'],['medical','✚','Trinoky'],['npc','◇','NPC'],['boss','♜','Boss'],['arena','⚔','Đấu trường'],['rank','↗','Xếp hạng'],['codex','▤','Kho dữ liệu'],['account','◎','Tài khoản'],['settings','⚙','Cài đặt']];
function card(title,body,footer='',extra=''){return `<article class="card ${extra}"><h3>${esc(title)}</h3>${body}<div class="card-actions">${footer}</div></article>`;}
const slotName=slot=>({weapon:'Vũ khí chính',armor:'Giáp chiến thuật',implant:'Cấy ghép'})[slot];
function icon(slot){return `<svg viewBox="0 0 64 64" aria-hidden="true" fill="currentColor">${slot==='weapon'?'<path d="M6 22h38v-6h8v6h9v9H35l-4 16H19l4-16H6z"/><path d="M12 17h22v3H12z"/>':slot==='armor'?'<path d="m17 9 10-4 5 10 5-10 10 4 12 18-12 8-4-8v32H21V27l-4 8-12-8z"/>':'<path d="M17 17h30v30H17zM9 9h8v8H9zm38 0h8v8h-8zM9 47h8v8H9zm38 0h8v8h-8zM26 4h4v13h-4zm9 0h4v13h-4zM26 47h4v13h-4zm9 0h4v13h-4zM4 26h13v4H4zm0 9h13v4H4zm43-9h13v4H47zm0 9h13v4H47z"/>'}</svg>`;}
function gearCard(g,shop=false,compact=false){const price=shopPrice(g,online?world?.discount||0:0);const equipped=Object.values(s.equipped).includes(g.id),owned=s.inventory.includes(g.id)||s.housing?.storage?.includes(g.id)||s.escrow?.includes(g.id),v=itemStats(s,g.id),c=calibration(s,g.id);return `<article class="gear-card tier${g.rarity} ${shop?'shop-row':''}"><div class="gear-label"><span>${slotName(g.slot)}</span><span>${rarities[g.rarity]}</span></div><div class="gear-body"><button class="gear-open" data-action="detail" data-id="${g.id}" aria-label="Chi tiết ${esc(g.name)}"><span class="gear-icon">${icon(g.slot)}<small>LV ${g.level}</small></span><span class="gear-info"><strong>${esc(g.name)}${c.level?` +${c.level}`:''}</strong><span class="gear-numbers">${g.slot==='weapon'?'DMG':g.slot==='armor'?'DEF':'PWR'}: ${v.power}${v.damage?` · ATK: +${v.damage}`:''}${v.health?` · HP: +${v.health}`:''}${v.armor?` · DEF: +${v.armor}`:''}${v.crit?` · CRIT: +${Math.round(v.crit*100)}%`:''}</span><span class="gear-sub">${equipped?'ĐANG TRANG BỊ':`CHẤT LƯỢNG ${v.quality}%`} / ${g.black?'KÊNH NGẦM':'HELIX SYSTEMS'}</span></span><span class="gear-grade">${v.quality}</span></button></div><div class="gear-actions" ${compact?'hidden':''}>${shop?button(owned?'Đã sở hữu':`${price.toLocaleString('vi')} ₡`,'buy',g.id,owned||g.level>s.level||s.credits<price||!!s.combat):button(equipped?'Đang dùng':'Trang bị','equip',g.id,equipped||g.level>s.level||!!s.combat)+button(`Bán ${Math.floor(g.price*0.4)} ₡`,'sell',g.id,equipped||!!s.combat)}</div></article>`;}
function inventory(){return inventoryView({s,section:inventoryTab,subsection:bagSection,filter,search,sort:bagSort,selected:bagSelected,craftCategory,hideUnavailable,inboxPage,esc,button,gearCard:g=>gearCard(g,false,true),icon,slotName});}
function shop(){const black=tab==='black',selling=shopTab==='sell',list=gear.filter(g=>selling?s.inventory.includes(g.id):g.black===black).filter(g=>filter==='all'||g.slot===filter),visible=filtered(list),pages=Math.max(1,Math.ceil(visible.length/10));catalogPage=Math.min(catalogPage,pages-1);return `<div class="merchant ${black?'underground':''}"><img src="/src/merchant.svg" alt="Thợ vũ khí tóc bạc trong xưởng công nghệ neon"><div class="merchant-title"><span>${black?'FREQUENCY / 09.71':'HELIX / WORKSHOP 07'}</span><h1>${black?'Chợ bóng tối':'Thợ vũ khí'}</h1></div><div class="merchant-dialogue"><b>${black?'VEX / MÔI GIỚI':'KAIA / THỢ CHẾ TẠO'}</b><p>${black?'Không hỏi nguồn gốc. Chọn thứ giúp bạn sống sót.':'Đừng để món đồ rẻ tiền quyết định số phận. Cần gì, runner?'}</p></div></div><div class="subtabs">${[['buy','Mua trang bị'],['sell','Bán trang bị']].map(([id,name])=>`<button class="${shopTab===id?'selected':''}" data-action="shop-tab" data-id="${id}">${name}</button>`).join('')}<span>${s.credits.toLocaleString('vi')} ₡</span></div>${toolbar(true)}<div class="section-label">${selling?'KHO CỦA BẠN':black?'HÀNG CẤM / SỬ THI & HUYỀN THOẠI':'DANH MỤC THIẾT BỊ'}<span>${visible.length} MỤC</span></div><div class="shop-list">${visible.slice(catalogPage*10,catalogPage*10+10).map(g=>gearCard(g,!selling)).join('')||'<p class="hint">Không có trang bị phù hợp.</p>'}</div><div class="pagination">${button('‹ Trước','catalog-page',String(catalogPage-1),catalogPage===0)}<span>TRANG ${catalogPage+1} / ${pages}</span>${button('Sau ›','catalog-page',String(catalogPage+1),catalogPage>=pages-1)}</div>`;}
function detail(){const g=gear.find(g=>g.id===selectedGear),price=shopPrice(g,online?world?.discount||0:0),reserved=s.housing?.storage?.includes(g.id)||s.escrow?.includes(g.id),v=itemStats(s,g.id),c=calibration(s,g.id),owned=s.inventory.includes(g.id),cost=upgradeCost(s,g.id),equipped=Object.values(s.equipped).includes(g.id);return `<section class="item-detail tier${g.rarity}"><div class="detail-top">${button('‹ Quay lại','close-detail')}<span>${rarities[g.rarity]} / ${g.black?'KÊNH NGẦM':'HELIX'}</span></div><h1>${esc(g.name)}${c.level?` +${c.level}`:''}</h1><div class="item-strip">LEVEL ${g.level} <span>${slotName(g.slot).toUpperCase()}</span><span>GEN ${g.rarity+1}</span></div><div class="detail-layout"><div class="detail-core"><div class="quality-heading"><span>CHẤT LƯỢNG</span><b>${v.quality}%</b></div><div class="quality-track"><i style="width:${v.quality}%"></i></div><div class="calibration-row"><div><span>NĂNG LỰC HIỆU CHUẨN</span><div class="calibration-boxes">${Array.from({length:5},(_,i)=>`<i class="${i<c.level?'filled':''}"></i>`).join('')}</div></div>${button(c.level>=5?'Đã tối đa':`Nâng cấp · ${cost} ₡`,'upgrade',g.id,!owned||g.level>s.level||!!s.combat||c.level>=5||s.credits<cost)}</div><p class="station-link">${button('Đến trạm hiệu chuẩn','nav','station')}</p><dl class="item-attributes"><div><dt>${g.slot==='weapon'?'SÁT THƯƠNG':g.slot==='armor'?'PHÒNG THỦ':'SỨC MẠNH'}</dt><dd>+${v.power}<small>${c.level?`+${c.level*2} từ hiệu chuẩn`:'Chỉ số cơ bản'}</small></dd></div><div><dt>SINH LỰC</dt><dd>+${v.health}<small>Từ module</small></dd></div><div><dt>TẤN CÔNG</dt><dd>+${v.damage}<small>Từ module</small></dd></div><div><dt>PHÒNG THỦ</dt><dd>+${v.armor}<small>Từ module</small></dd></div><div><dt>CHÍ MẠNG</dt><dd>+${Math.round(v.crit*100)}%<small>Từ module</small></dd></div></dl><blockquote>${esc(g.description)}<br><em>“Thứ sống sót không phải luôn là thứ mạnh nhất. Nó là thứ được sửa chữa đúng lúc.”</em></blockquote><div class="detail-controls">${owned?button(equipped?'Đang trang bị':'Trang bị','equip',g.id,equipped||g.level>s.level||!!s.combat)+button(`Bán · ${Math.floor(g.price*0.4)} ₡`,'sell',g.id,equipped||!!s.combat):button(reserved?'Đang ở kho / chợ':`Mua · ${price} ₡`,'buy',g.id,reserved||g.level>s.level||s.credits<price||!!s.combat)}</div></div><div class="module-panel"><div class="section-label">MODULE NÂNG CẤP <span>${slots(s,g.id)} / 3 KHE</span></div>${Array.from({length:3},(_,i)=>{const m=modules.find(m=>m.id===c.modules[i]),locked=i>=slots(s,g.id);return `<div class="module-slot ${locked?'locked':''}"><div class="module-tag">KHE MODULE ${i+1}</div><div class="module-body"><span class="module-icon">${icon('implant')}</span><div><h3>${locked?`Mở ở hiệu chuẩn +${i*2}`:m?m.name:'Khe module trống'}</h3><p>${locked?'Nâng cấp trang bị để mở khóa':m?m.label:'Chọn module để tăng chỉ số'}</p></div></div>${!locked?`<form class="module-form" data-slot="${i}"><select name="module" aria-label="Module khe ${i+1}">${modules.map(mod=>`<option value="${mod.id}" ${mod.id===m?.id?'selected':''}>${mod.name} / ${mod.label} / ${mod.price} ₡</option>`).join('')}</select><button ${!owned||g.level>s.level||!!s.combat?'disabled':''}>${m?'Thay':'Lắp'}</button></form>`:''}</div>`;}).join('')}<p class="hint">Module tính vào chỉ số khi trang bị đang được sử dụng. Lắp mới hoặc thay module đều tốn credits; module cũ không được hoàn lại.</p></div></div></section>`;}
function filtered(items){return items.filter(x=>x.name.toLocaleLowerCase('vi').includes(search.toLocaleLowerCase('vi')));}
function toolbar(options=false){return `<div class="toolbar"><input id="search" aria-label="Tìm kiếm nội dung" placeholder="Tìm trong mục này…" value="${esc(search)}">${options?`<select id="filter" aria-label="Loại trang bị"><option value="all">Tất cả loại</option>${['weapon','armor','implant'].map((x,i)=>`<option value="${x}" ${filter===x?'selected':''}>${['Vũ khí','Giáp','Cấy ghép'][i]}</option>`).join('')}</select>`:''}</div>`;}
function combat(){const f=s.combat;if(!f)return '';return `<div class="combat"><div class="eyebrow">${f.pvp?(online?'PVP BẤT ĐỒNG BỘ':'ĐỐI THỦ MÔ PHỎNG'):'GIAO TRANH'} / LƯỢT ${f.turn+1}</div><h2>${esc(f.name)}</h2><p>Cấp ${f.level} · ATK ${f.attack} · DEF ${f.defense}</p><div class="bar danger"><i style="width:${Math.max(0,f.currentHp/f.hp*100)}%"></i></div><p>${Math.max(0,f.currentHp)} / ${f.hp} HP</p>${!settings(s).hideDamageMeter&&s.lastHit?.name===f.name?`<div class="attack-meter"><span>ĐÒN VỪA ĐÁNH · ${s.lastHit.damage}${s.lastHit.critical?' CHÍ MẠNG':''}</span><div class="bar"><i style="width:${Math.min(100,s.lastHit.damage/f.hp*100)}%"></i></div></div>`:''}<div class="actions">${button('Tấn công','attack')}${button('Xung điện · 3 EN','skill','',s.energy<3)}${button('Thuốc · 25 ₡','heal','',s.credits<25)}${button('Rút lui','escape')}</div></div>`;}
function authView(){return online?`<div class="hero"><div class="eyebrow">SERVER SESSION</div><h1>${esc(s.name)}</h1><p>Nhân vật lưu trên server. Dùng cùng tài khoản để tiếp tục trên thiết bị khác. Phiên đăng nhập có thể hết hạn khi server khởi động lại.</p>${button('Đăng xuất','logout')}</div>`:`<div class="hero"><div class="eyebrow">KẾT NỐI SERVER</div><h1>Vào mạng.<br><span>Giữ danh tính.</span></h1><p>Đăng nhập để lưu nhân vật trên server và đấu với nhân vật người chơi khác. Nhân vật online và tiến trình khách được lưu riêng.</p><form id="auth-form"><input name="username" placeholder="Tên tài khoản" aria-label="Tên tài khoản" autocomplete="username" pattern="[a-zA-Z0-9_]{3,24}" required maxlength="24"><input name="password" type="password" placeholder="Mật khẩu (ít nhất 8 ký tự)" aria-label="Mật khẩu" autocomplete="current-password" minlength="8" maxlength="128" required><div class="actions"><button name="mode" value="login">Đăng nhập</button><button name="mode" value="register">Tạo tài khoản</button></div></form></div>`;}
function page(){if(tab==='settings')return settingsView({s,online,draft:settingsDraft||settings(s),esc,button,returnTab:settingsReturn});if(['bazaar','alley','pets','tavern','coast'].includes(tab))return bazaarView({s,tab,world,online,esc,button});if(tab==='commercial')return commercialView({s,esc,button});if(tab==='rail')return railView({s,station:railStation,esc,button});if(publicProfile)return button('‹ Đóng tài sản công khai','public-profile-close')+publicAssetsView(publicProfile,esc);if(tab==='missions'&&selectedMilestone)return milestonesView({s,esc,button,selected:selectedMilestone});if(tab==='cores'&&!selectedGear)return coresView({s,button});if(tab==='chat'&&!selectedGear)return commsView({s,world,online,mode:chatMode,replyId,attached,esc,button});if(tab==='reputation'&&!selectedGear)return reputationView({world,online,esc,button});if(['market','corporation','headquarters','housing','cosmetics','medical','commercial'].includes(tab)&&!selectedGear)return worldView({s,tab,world,online,esc,button,marketSection,marketQuery,marketSlot,marketSort,marketDraft});if(tab==='dungeon'&&!selectedGear)return dungeonView({s,esc,button,combat});if(selectedGear)return detail();if(['hub','station','printer','bank','exchange'].includes(tab))return serviceView({s,tab,esc,button,gearCard,options:stationOptions,calibrationId,financeAmount,world,online});const m=maps.find(x=>x.id===s.map);switch(tab){case 'terminal':return `<div class="hero"><div class="eyebrow">KẾT NỐI ĐÃ MÃ HÓA / SECTOR ${String(maps.indexOf(m)+1).padStart(2,'0')}</div><h1>Thành phố đã quên.<br><span>Bạn thì chưa.</span></h1><p>${esc(m.description)}</p><div class="actions">${button(s.dungeon?'Tiếp tục dungeon':'Vào dungeon','nav','dungeon')}${button('Khám phá · 2 EN','fight','',!!s.dungeon||!!s.combat||s.energy<2)}${button('Tìm nhiệm vụ','nav','missions')}${button('Nghỉ tại trạm','rest','',!!s.dungeon||!!s.combat)}</div><div class="hero-grid"><span>ĐỊA ĐIỂM<b>${esc(m.name)}</b></span><span>PHE KIỂM SOÁT<b>${esc(m.faction)}</b></span><span>TRẠNG THÁI<b class="green">${s.combat?'ĐANG CHIẾN ĐẤU':'TÍN HIỆU ỔN ĐỊNH'}</b></span></div></div>${keysView(s,esc,button,{assemble:true})}${combat()}<div class="section-head"><h2>Nhật ký hệ thống</h2><span>LIVE FEED</span></div><div class="feed">${s.log.map((x,i)=>`<p><span>${String(i+1).padStart(2,'0')}</span> ${esc(x)}</p>`).join('')}</div>`;
case 'map':return toolbar()+`<p class="hint">Di chuyển tốn 1 EN. Có thể vào khu vực cao hơn tối đa 2 cấp.</p><div class="grid">${filtered(maps).map(x=>card(x.name,`<div class="meta">Cấp ${x.level} · ${esc(x.faction)}</div><p>${esc(x.description)}</p>`,button(x.id===s.map?'Đang ở đây':x.level>s.level+2?'Chưa mở':'Di chuyển','move',x.id,x.id===s.map||x.level>s.level+2||!areaAccess(s,x)||!!s.dungeon||!!s.combat||s.energy<1))).join('')}</div>`;
case 'missions':return communityView({world,s,online,esc,button})+guidanceView(button)+milestonesView({s,esc,button})+'<div class="section-label">CONTRACTS / NHIỆM VỤ CÁ NHÂN <span>'+quests.length+' HỢP ĐỒNG</span></div>'+toolbar()+`<p class="hint">Tối đa 5 nhiệm vụ đang nhận. Chỉ lượt hạ địch sau khi nhận mới được tính.</p><div class="grid">${filtered(quests).sort((a,b)=>Number(s.active.includes(b.id))-Number(s.active.includes(a.id))).map(q=>{const active=s.active.includes(q.id),done=s.completed.includes(q.id),progress=questProgress(s,q);return card(q.name,`<div class="meta">Cấp ${q.level} · ${q.target==='boss'?'Hạ boss':'Hạ địch'} ×${q.count}</div><p>${esc(q.story)}</p><p class="reward">+${q.xp} XP / +${q.credits} ₡ ${active?`· ${progress}/${q.count}`:''}</p>`,button(done?'Đã hoàn thành':active?'Nhận thưởng':'Nhận nhiệm vụ',active?'claim':'accept',q.id,done||q.level>s.level+2||active&&(progress<q.count||!!s.combat)||!active&&s.active.length>=5));}).join('')}</div>`;
case 'inventory':return inventory();
case 'shop':case 'black':return shop();
case 'npc':return toolbar()+`<p class="hint">${npcs.length} cư dân của thành phố. Đến khu vực của họ để trò chuyện.</p><div class="grid">${filtered(npcs).map(n=>card(n.name,`<div class="meta">${esc(maps.find(m=>m.id===n.map).name)} · ${esc(n.faction)}</div>`,button('Trò chuyện','talk',n.id,n.map!==s.map||!!s.combat))).join('')}</div>`;
case 'boss':return combat()+toolbar()+`<div class="grid">${filtered(bosses).map(b=>card(b.name,`<div class="meta">Cấp ${b.level} · ${b.hp} HP · ${b.attack} ATK</div><p>${esc(b.description)}</p><p class="reward">+${b.xp} XP / +${b.credits} ₡</p>`,button('Thách đấu · 2 EN','boss',b.id,b.map!==s.map||!!s.dungeon||!!s.combat||s.energy<2))).join('')}</div>`;
case 'arena':if(online)return `<div class="hero"><div class="eyebrow">PVP / BẤT ĐỒNG BỘ</div><h1>Đấu trường<br><span>runner.</span></h1><p>Đấu với bản sao phòng thủ của nhân vật người chơi thật. Đối thủ do máy điều khiển; không yêu cầu họ online cùng lúc. Kết quả và phần thưởng của bạn được xử lý trên server.</p><p>${s.wins} thắng / ${s.losses} thua</p>${button('Nghỉ tại trạm','rest','',!!s.dungeon||!!s.combat)}</div>${combat()}<div class="grid" style="margin-top:20px">${players.filter(p=>p.id!==online.id).map(p=>card(p.name,`<p>Cấp ${p.level} · ${p.score} điểm</p>`,button('Thách đấu · 3 EN','pvp',p.id,!!s.dungeon||!!s.combat||s.energy<3))).join('')||'<p class="hint">Chưa có người chơi khác. Cần thêm một tài khoản tham gia đấu trường.</p>'}</div>`;return `<div class="hero"><div class="eyebrow">ARENA / ĐỐI THỦ MÔ PHỎNG</div><h1>Không có chỗ<br><span>cho tín hiệu yếu.</span></h1><p>Đấu tay đôi theo lượt với runner máy có cấp tương đương. Bản này chưa kết nối người chơi khác.</p><div class="actions">${button('Tìm đối thủ · 3 EN','pvp','',!!s.dungeon||!!s.combat||s.energy<3)}${button('Nghỉ tại trạm','rest','',!!s.dungeon||!!s.combat)}</div><div class="hero-grid"><span>THẮNG<b>${s.wins}</b></span><span>THUA<b>${s.losses}</b></span><span>ĐIỂM ĐẤU<b>${Math.max(0,s.wins*25-s.losses*10)}</b></span></div></div>${combat()}`;
case 'rank':{if(online)return `<p class="hint">Bảng xếp hạng từ tài khoản thật trên server này, xếp theo điểm đấu và cấp.</p><div class="table-wrap"><table><thead><tr><th>Hạng</th><th>Runner</th><th>Cấp</th><th>Điểm đấu</th></tr></thead><tbody>${players.map((r,i)=>`<tr class="${r.id===online.id?'you':''}"><td>${i+1}</td><td>${esc(r.name)}</td><td>${r.level}</td><td>${r.score}</td></tr>`).join('')}</tbody></table></div>`;const runners=Array.from({length:12},(_,i)=>({name:['NULL','Mika.exe','Ghost Wire','Redline','NoSignal','Vex','Echo-7','Kha','Raven','Linh','Circuit','Kite'][i],score:300-i*24,level:30-i*2}));runners.push({name:s.name,score:Math.max(0,s.wins*25-s.losses*10),level:s.level,you:true});runners.sort((a,b)=>b.score-a.score);return `<p class="hint">Bảng xếp hạng cục bộ, các runner khác là dữ liệu mô phỏng.</p><div class="table-wrap"><table><thead><tr><th>Hạng</th><th>Runner</th><th>Cấp</th><th>Điểm đấu</th></tr></thead><tbody>${runners.map((r,i)=>`<tr class="${r.you?'you':''}"><td>${String(i+1).padStart(2,'0')}</td><td>${esc(r.name)}${r.you?' / BẠN':''}</td><td>${r.level}</td><td>${r.score}</td></tr>`).join('')}</tbody></table></div>`;}
case 'account':return profileView({s,online,world,section:profileSection,activeBadgeSlot,esc,button,auth:authView()});
case 'codex':return `<div class="hero"><div class="eyebrow">DATABASE / ${contentCount} RECORDS</div><h1>Kho dữ liệu<br><span>thành phố tro.</span></h1><p>Thế giới và nội dung riêng lấy cảm hứng từ RPG văn bản cyberpunk. Nội dung được tạo theo mẫu có phân cấp; có chế độ khách và tài khoản online.</p></div><div class="grid">${Object.entries(content).map(([k,v],i)=>card(['Khu vực','Trang bị','NPC','Địch PvE','Boss','Nhiệm vụ'][i],`<strong class="big">${v.length}</strong> hồ sơ`)).join('')}</div><article class="card"><h3>Cách chơi</h3><p>Nhận nhiệm vụ tại khu vực phù hợp → khám phá và hạ địch → nhận thưởng → mua, trang bị và di chuyển tới khu vực mới. Nghỉ tại trạm để hồi đầy HP và năng lượng. Boss gây xung điện mỗi lượt thứ ba; thuốc hồi 45 HP nhưng vẫn tiêu tốn lượt.</p><p>Chế độ khách lưu trên thiết bị; chế độ tài khoản lưu trên server. Tên runner tối đa 24 ký tự.</p><form id="name-form"><input name="runner" maxlength="24" aria-label="Tên runner" value="${esc(s.name)}"><button>Đổi tên</button></form><p>${online?'Nhân vật online được lưu trên server.':button('Bắt đầu lại','reset')}</p></article>`;
}}
function compactPlayer(st){return `<div class="compact-player"><div class="level-badge">${s.level}</div><div class="compact-progress"><div class="bar"><i style="width:${s.hp/st.maxHp*100}%"></i></div><div class="compact-xp"><i style="width:${s.xp/(s.level*60)*100}%"></i><b>${s.xp.toLocaleString('vi')} / ${(s.level*60).toLocaleString('vi')} XP</b></div><small>${s.credits.toLocaleString('vi')} ₡ / ${resources(s).units} UNIT <span>HP ${s.hp}/${st.maxHp} · EN ${s.energy}/30</span></small></div><button data-action="settings-open" aria-label="Mở cài đặt">⚙</button></div>`;}
function render(){
 const preferences=settings(s);document.documentElement.lang=preferences.language;document.documentElement.classList.remove('ui-small','ui-medium','ui-large','ui-auto');document.documentElement.classList.add('ui-'+preferences.uiSize);document.documentElement.classList.toggle('in-settings',tab==='settings');document.documentElement.classList.toggle('npc-motion',preferences.animateNPC&&!preferences.hideNPC);document.documentElement.classList.toggle('hide-npc-art',preferences.hideNPC);document.documentElement.classList.toggle('work-motion',preferences.animateWork);sounds.configure(preferences);
 if(!uiBoot){lastVictory=s.lastVictory?.id;uiBoot=true;}else if(s.lastVictory?.id&&s.lastVictory.id!==lastVictory){lastVictory=s.lastVictory.id;if(!preferences.disableVictory)victoryModal=s.lastVictory;}if(preferences.disableVictory)victoryModal=null;
 if(tab==='market')marketRendered=JSON.stringify(world?.market||[]);
 if(!online){migrateRail(s);settleInbox(s);}
 const openInventoryPanels=[...document.querySelectorAll('.inventory-settings[open]')].map(v=>v.dataset.panel);
 if(selectedGear&&!gear.some(g=>g.id===selectedGear))selectedGear=null;
 const st=stats(s),compact=!selectedGear&&['hub','rail','missions','bazaar','alley','pets','tavern','coast','market','corporation','headquarters','housing','cosmetics','medical','commercial'].includes(tab),aura=cosmetics.find(c=>c.id===s.aura)?.color||'#b7d9d2';
 if(tab==='chat'&&chatMode==='global')lastSeenChat=world?.messages.at(-1)?.time||lastSeenChat;
 try{if(!online)localStorage.setItem('cyper-save',JSON.stringify(s));}catch{notice='Trình duyệt không cho lưu tiến trình. Dữ liệu chỉ tồn tại trong phiên này.';}
 const latest=world?.messages.at(-1),ticker=latest?`${esc(latest.name)}: ${esc(latest.text)}`:'Kênh toàn cầu / Chưa có tin nhắn';
 document.querySelector('#app').innerHTML=`<aside><a class="brand" href="#" data-action="nav" data-id="hub">CYPER<span>// ZERO</span></a><div class="sub-brand">TEXT RPG · THÀNH PHỐ TRO</div><nav>${tabs.map(([id,icon,label])=>`<button class="nav ${tab===id?'active':''}" data-action="nav" data-id="${id}"><span>${icon}</span>${uiLabel(label,preferences.language)}${id==='missions'?`<small>${s.active.length}</small>`:''}</button>`).join('')}</nav><div class="aside-foot"><i></i> ${online?'SERVER SESSION':'LOCAL SESSION'}<br><small>${online?'Tiến trình lưu trên server':'Tiến trình tự lưu trên thiết bị'}</small></div></aside><div style="--aura:${aura}" class="main ${tab==='chat'?'comms-layout':''} ${tab==='account'?'profile-layout':''} ${tab==='settings'?'settings-layout':''} ${compact?'city-layout':''} ${selectedGear?'show-detail':''} ${tab==='dungeon'&&s.dungeon?'dungeon-active':''}"><header><details class="mobile-menu"><summary aria-label="Mở menu">☰</summary><div>${tabs.map(([id,icon,label])=>`<button data-action="nav" data-id="${id}">${icon} ${uiLabel(label,preferences.language)}</button>`).join('')}</div></details><span>NET / ${uiLabel(tabs.find(t=>t[0]===tab)[2],preferences.language).toLocaleUpperCase('vi')}</span><span class="wallet">${s.credits.toLocaleString('vi')} ₡ <small>${resources(s).units} U</small></span></header>${['account','chat','inventory','settings'].includes(tab)?'':compact?compactPlayer(st):`<div class="player"><div class="avatar">${esc(s.name.slice(0,1).toUpperCase())}</div><div class="identity"><b>${esc(s.name)}</b><small>RUNNER / CẤP ${s.level}</small></div><div class="vital"><label>SINH LỰC <span>${s.hp}/${st.maxHp}</span></label><div class="bar"><i style="width:${s.hp/st.maxHp*100}%"></i></div></div><div class="vital energy"><label>NĂNG LƯỢNG <span>${s.energy}/30</span></label><div class="bar"><i style="width:${s.energy/30*100}%"></i></div></div><div class="xp">${s.xp}/${s.level*60} XP<br><small>ATK ${st.attack} / DEF ${st.defense}</small></div></div>`}${compact?`<button class="chat-ticker" data-action="nav" data-id="chat">${ticker}</button>`:''}<main><div class="client-notice" role="status" ${clientNotice?'':'hidden'}><span>${esc(clientNotice)}</span>${button('×','client-notice-close')}</div>${tab==='hub'?introCards():''}${s.work&&tab!=='commercial'&&tab!=='settings'?`<div class="work-resume">${workPanel(s,button,esc)}${button('Đến khu thương mại','nav','commercial')}</div>`:''}${s.dungeon&&tab!=='dungeon'?`<div class="dungeon-resume">${button('▥ Tiếp tục dungeon · tầng '+s.dungeon.floor,'nav','dungeon')}</div>`:''}${notice?`<div class="notice" role="status">${esc(notice)}</div>`:''}${page()}</main><footer>CYPER // ZERO <span>v0.9 / ${online?'Online':'Khách cục bộ'} · ${contentCount} mục nội dung</span></footer></div><div class="bottom-nav" role="navigation" aria-label="Điều hướng chính">${[['hub','◫','Bản đồ'],['inventory','▣','Túi đồ'],['missions','≡','Nhiệm vụ'],['chat','▱','Trò chuyện'],['account','◎','Hồ sơ']].map(([id,icon,label])=>`<button class="${tab===id||(id==='account'&&tab==='settings')||(id==='hub'&&['map','rail','station','printer','bank','exchange','shop','black','dungeon','terminal','commercial','bazaar','alley','pets','tavern','coast','market','medical','cosmetics','housing','headquarters','corporation'].includes(tab))?'active':''}" data-action="nav" data-id="${id}"><span>${icon}</span>${uiLabel(label,preferences.language)}${id==='missions'&&s.active.length||id==='chat'&&((world?.messages.at(-1)?.time||0)>lastSeenChat||(world?.guildMessages.at(-1)?.time||0)>lastSeenGuild||world?.mail.some(m=>m.recipient===online?.id&&!m.read)||s.notifications?.some(n=>!n.read))?'<i></i>':''}</button>`).join('')}</div>${modalView()}`;
 const modal=document.querySelector('.modal-overlay');if(modal)modal.querySelector('button')?.focus();
 const permission=document.querySelector('#notification-permission');if(permission)permission.textContent=!('Notification' in window)?'Trình duyệt chưa hỗ trợ thông báo.':Notification.permission==='granted'?'Đã cấp quyền thông báo.':Notification.permission==='denied'?'Đã chặn thông báo; đổi quyền trong cài đặt trình duyệt.':'Chưa cấp quyền thông báo.';
 if(s.work)document.querySelectorAll('[data-action]').forEach(el=>{if(workBlockedActions.has(el.dataset.action))el.disabled=true;});
 for(const panel of openInventoryPanels){const details=document.querySelector(`.inventory-settings[data-panel="${panel}"]`);if(details)details.open=true;}
 if(tab==='chat'){
  const text=document.querySelector('#chat-text');if(text){text.value=chatDrafts[chatMode]||'';document.querySelector('#chat-count').textContent=text.value.length+' / 256';}
  const item=document.querySelector('#chat-item');if(item)item.value=attachedGear;
  const mail=document.querySelector('#mail-text');if(mail)mail.value=mailDraft;
  const recipient=document.querySelector('.mail-compose [name="id"]');if(recipient&&mailRecipient)recipient.value=mailRecipient;
  const feed=document.querySelector('.chat-feed');if(feed)feed.scrollTop=feed.scrollHeight;
  sizeChat();
  if(chatMode==='guild')lastSeenGuild=world?.guildMessages.at(-1)?.time||lastSeenGuild;
 }
}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;e.preventDefault();const a=b.dataset.action,id=b.dataset.id;if(busy)return;sounds.play('effect');notice='';let ok=true;
if(a==='settings-open'){settingsReturn=tab==='settings'?'hub':tab;settingsDraft={...settings(s)};tab='settings';render();window.scrollTo(0,0);return;}if(a==='settings-back'){tab=settingsReturn;settingsDraft=null;render();window.scrollTo(0,0);return;}if(a==='victory-close'){victoryModal=null;render();return;}if(a==='client-notice-close'){clientNotice='';render();return;}if(a==='delete-cancel'){pendingDelete=null;render();return;}if(a==='delete-confirm'){await confirmDeletion();return;}if(a==='notification-permission'){if(settings(s).neverAskNotifications){notice='Áp dụng lựa chọn cho phép thông báo trước.';render();return;}if(!('Notification' in window)){notice='Trình duyệt không hỗ trợ thông báo.';render();return;}try{await Notification.requestPermission();}catch{}render();return;}
if(a==='auth-open'){tab='account';profileSection='auth';render();return;}if(a==='open-assets'){tab='account';profileSection='assets';render();return;}if(a==='open-global-chat'){tab='chat';chatMode='global';render();return;}if(a==='market-section'){marketSection=id==='mine'?'mine':'browse';tab='market';marketQuery='';marketSlot='all';marketSort='newest';render();window.scrollTo(0,0);return;}if(a==='market-refresh'){busy=true;try{await refreshWorld();notice='Đã cập nhật thị trường.';}catch(err){notice=err.message;}finally{busy=false;render();}return;}
if(a==='craft-category'){craftCategory=id;render();return;}if(a==='inbox-page'){inboxPage=Number(id);render();return;}if(a==='rail-station'){railStation=id;render();window.scrollTo(0,0);return;}if(a==='rail-back'){railStation=null;render();window.scrollTo(0,0);return;}if(a==='public-self'){busy=true;try{publicProfile=online?(await request('/api/profile/'+online.id)).assets:publicAssets(s);}catch(err){notice=err.message;}finally{busy=false;render();window.scrollTo(0,0);}return;}if(a==='public-profile-close'){publicProfile=null;render();return;}if(a==='public-profile'){busy=true;try{publicProfile=(await request('/api/profile/'+encodeURIComponent(id))).assets;}catch(err){notice=err.message;}finally{busy=false;render();window.scrollTo(0,0);}return;}if(a==='bag-filter'){filter=id;render();return;}if(a==='bag-section'){bagSection=id;render();return;}if(a==='bag-clear'){bagSelected.clear();render();return;}
if(a==='milestone-detail'){selectedMilestone=id;render();window.scrollTo(0,0);return;}if(a==='close-milestone'){selectedMilestone=null;render();return;}if(a==='profile-tab'){profileSection=id;activeBadgeSlot=null;render();window.scrollTo(0,0);return;}if(a==='badge-slot'){activeBadgeSlot=Number(id);render();return;}if(a==='badge-close'){activeBadgeSlot=null;render();return;}if(a==='chat-tab'){chatMode=id;replyId=null;attached=false;attachedGear='';render();return;}if(a==='reply'){replyId=id;render();document.querySelector('#chat-text')?.focus();return;}if(a==='reply-cancel'){replyId=null;render();return;}if(a==='attach-item'){attached=!attached;render();return;}
if(a==='catalog-page'){catalogPage=Number(id);render();window.scrollTo(0,0);return;}if(a==='detail'){selectedGear=id;render();window.scrollTo(0,0);return;}if(a==='close-detail'){selectedGear=null;render();return;}if(a==='inventory-tab'){tab='inventory';inventoryTab=id;selectedGear=null;search='';filter='all';bagSelected.clear();render();return;}if(a==='shop-tab'){catalogPage=0;shopTab=id;selectedGear=null;search='';render();return;}
if(a==='logout'){busy=true;try{await request('/api/logout',{});online=null;chatDrafts={};mailDraft='';mailRecipient='';replyId=null;chatMode='global';profileSection='profile';s=fresh();uiBoot=false;try{const v=JSON.parse(localStorage.getItem('cyper-save'));if(v?.version===1)s=v;}catch{}tab='account';await refreshWorld();}catch(err){notice=err.message;}finally{busy=false;render();}return;}
if(!online&&!workAllows(s,a)){notice='Nhận thưởng hoặc hủy công việc trước.';render();return;}
if(online&&a!=='nav'&&a!=='reset'){busy=true;b.disabled=true;try{const result=await request('/api/action',{action:a,id,ids:a==='bulk-sell'?[...bagSelected]:undefined,count:a==='craft'?Number(b.closest('.craft-form')?.querySelector('[name="count"]')?.value||1):undefined,slot:activeBadgeSlot,boost:stationOptions.boost,protect:stationOptions.protect,black:selectedGear?gear.find(g=>g.id===selectedGear).black:tab==='black'});s=result.state;online=result.user;if(a==='bulk-sell')bagSelected.clear();if(a==='pin-badge')activeBadgeSlot=null;if(a==='calibrate'||a==='print')notice=s.log[0];if(a==='sell')selectedGear=null;if(a==='enter-dungeon')tab='dungeon';if(a==='fight')tab='terminal';if(a==='talk'||a==='alley-rumor')notice=s.log[0];await Promise.all([refreshPlayers(),refreshWorld()]);}catch(err){notice=err.message;}finally{busy=false;render();}return;}if(a==='nav'){sounds.play('effect');railStation=null;publicProfile=null;selectedMilestone=null;activeBadgeSlot=null;busy=true;financeAmount=1;if(id==='station'&&selectedGear)calibrationId=selectedGear;catalogPage=0;selectedGear=null;tab=id;if(id==='settings'){settingsReturn='hub';settingsDraft={...settings(s)};}search='';filter='all';try{await refreshWorld();}catch{}window.scrollTo(0,0);if(online&&(id==='arena'||id==='rank'))try{await refreshPlayers();}catch(err){notice=err.message;}busy=false;}else if(['tutorial-dismiss','updates-dismiss'].includes(a))ok=settingsAction(s,{action:a});else if(a.startsWith('work-')){ok=workAction(s,{action:a,id});if(ok)notice=s.log[0];}else if(a==='key-assemble'){ok=railAction(s,{action:a,id});if(ok)notice=s.log[0];}else if(a==='enter-dungeon'){ok=enterDungeon(s);if(ok)tab='dungeon';}else if(a==='leave-dungeon')ok=leaveDungeon(s);else if(a==='dungeon-step')ok=stepDungeon(s,id);else if(a==='move')ok=move(s,id);else if(a==='fight'){ok=startFight(s);tab='terminal';}else if(a==='boss')ok=startFight(s,'boss');else if(a==='pvp')ok=pvp(s);else if(['attack','skill','heal','escape'].includes(a))ok=turn(s,a);else if(a==='rest')ok=rest(s);else if(a==='buy')ok=buy(s,id,selectedGear?gear.find(g=>g.id===selectedGear).black:tab==='black');else if(a==='upgrade')ok=upgrade(s,id);else if(a==='print'){ok=printItem(s,id);if(ok)notice=s.log[0];}else if(a==='calibrate'){ok=calibrateItem(s,id,stationOptions);if(ok)notice=s.log[0];}else if(a==='equip')ok=equip(s,id);else if(a==='sell'){ok=sell(s,id);if(ok)selectedGear=null;}else if(a==='accept')ok=accept(s,id);else if(a==='claim')ok=claim(s,id);else if(a==='talk'){const n=npcs.find(n=>n.id===id);if(n.map===s.map){note(s,`${n.name}: ${n.dialogue}`);notice=`${n.name}: ${n.dialogue}`;}}else if(['alley-rumor','medical','cosmetic','housing-rent','housing-rest','housing-deposit','housing-withdraw'].includes(a)){ok=cityAction(s,{action:a,id});if(ok&&a==='alley-rumor')notice=s.log[0];}else if(['milestone-claim','scavenge','core-craft','core-recharge','pin-badge','notifications-read'].includes(a)){ok=progressionAction(s,{action:a,id,slot:activeBadgeSlot});if(ok){if(a==='pin-badge')activeBadgeSlot=null;else if(a!=='notifications-read')notice=s.log[0];}}else if(['quick-set','item-use','supply-buy','craft','inbox-claim','inbox-claim-all','loadout-save','loadout-apply','bulk-sell'].includes(a)){ok=inventoryAction(s,{action:a,id,count:a==='craft'?Number(b.closest('.craft-form')?.querySelector('[name="count"]')?.value||1):undefined,ids:[...bagSelected]});if(ok){notice=s.log[0];if(a==='bulk-sell')bagSelected.clear();}}else if(['shelf-unlock','pet-buy','pet-select'].includes(a)){ok=assetAction(s,{action:a,id});if(ok)notice=s.log[0];}else if(a==='rep-give'||a==='mail-read'||a.startsWith('market-')||a.startsWith('corp-')){notice='Đăng nhập để dùng dịch vụ này.';}else if(a==='reset'){if(confirm('Xóa tiến trình trên thiết bị này và bắt đầu lại?')){s=fresh();tab='terminal';}}if(!ok)notice='Chưa đủ điều kiện thực hiện hành động này.';render();});
document.addEventListener('keydown',e=>{const modal=document.querySelector('.modal-overlay');if(modal){if(e.key==='Escape'){pendingDelete=null;victoryModal=null;render();}if(e.key==='Tab'){const buttons=[...modal.querySelectorAll('button:not(:disabled)')],i=buttons.indexOf(document.activeElement);e.preventDefault();buttons[(i+(e.shiftKey?-1:1)+buttons.length)%buttons.length]?.focus();}return;}if(tab!=='dungeon'||selectedGear||busy||e.ctrlKey||e.metaKey||e.altKey||e.target.closest('input,select,textarea,button,summary'))return;const direction={ArrowUp:'up',ArrowDown:'down',ArrowLeft:'left',ArrowRight:'right',w:'up',s:'down',a:'left',d:'right'}[e.key];if(direction){e.preventDefault();document.querySelector(`.dungeon-controls [data-id="${direction}"]`)?.click();}});
document.addEventListener('input',e=>{if(e.target.dataset.setting==='musicVolume'){settingsDraft.musicVolume=Number(e.target.value);document.querySelector('#music-volume').textContent=e.target.value+'%';return;}if(e.target.matches('.market-compose [name="price"]'))marketDraft.price=e.target.value;if(e.target.id==='market-query'){marketQuery=e.target.value;const pos=e.target.selectionStart;render();const input=document.querySelector('#market-query');input.focus();input.setSelectionRange(pos,pos);}if(e.target.id==='chat-text'){chatDrafts[chatMode]=e.target.value;const count=document.querySelector('#chat-count');if(count)count.textContent=e.target.value.length+' / 256';}if(e.target.id==='mail-text')mailDraft=e.target.value;if(e.target.id==='search'){search=e.target.value;catalogPage=0;const pos=e.target.selectionStart;render();const input=document.querySelector('#search');input.focus();input.setSelectionRange(pos,pos);}});
document.addEventListener('change',async e=>{if(e.target.dataset.setting){const key=e.target.dataset.setting;settingsDraft[key]=e.target.type==='checkbox'?e.target.checked:e.target.type==='range'?Number(e.target.value):e.target.value;if(key==='language')render();return;}if(e.target.matches('.market-compose [name="id"]')){marketDraft.id=e.target.value;return;}if(e.target.id==='market-slot'){marketSlot=e.target.value;render();return;}if(e.target.id==='market-sort'){marketSort=e.target.value;render();return;}if(e.target.id==='hide-unavailable'){hideUnavailable=e.target.checked;render();return;}if(e.target.dataset.selectGear){const id=e.target.dataset.selectGear;if(e.target.checked)bagSelected.add(id);else bagSelected.delete(id);render();return;}if(e.target.id==='bag-sort'){bagSort=e.target.value;render();return;}if(e.target.dataset.privacy){if(busy)return;busy=true;try{const payload={action:'privacy',id:e.target.dataset.privacy,visible:e.target.checked};if(online){const result=await request('/api/action',payload);s=result.state;online=result.user;}else assetAction(s,payload);notice='Đã lưu quyền riêng tư.';}catch(err){notice=err.message;}finally{busy=false;render();}return;}if(e.target.id==='chat-channel'){chatMode=e.target.value;replyId=null;attached=false;render();return;}if(e.target.id==='chat-item'){attachedGear=e.target.value;return;}if(e.target.matches('.mail-compose [name="id"]')){mailRecipient=e.target.value;return;}if(e.target.id==='calibration-item'){calibrationId=e.target.value;render();return;}if(['boost-calibration','protect-calibration'].includes(e.target.id)){stationOptions[e.target.id==='boost-calibration'?'boost':'protect']=e.target.checked;render();return;}if(e.target.id==='filter'){filter=e.target.value;catalogPage=0;render();}});
document.addEventListener('submit',async e=>{if(['settings-form','delete-form'].includes(e.target.id)){e.preventDefault();await submitSettings(e);return;}if(e.target.matches('.inventory-form,.asset-form')){e.preventDefault();if(busy)return;busy=true;const payload={action:e.target.dataset.kind,id:new FormData(e.target).get('id'),slot:Number(e.target.dataset.slot)};try{if(online){const result=await request('/api/action',payload);s=result.state;online=result.user;}else if(!(e.target.matches('.asset-form')?assetAction:inventoryAction)(s,payload))throw new Error('Chưa đủ điều kiện.');notice='Đã lưu lựa chọn.';}catch(err){notice=err.message;}finally{busy=false;render();}return;}if(e.target.id==='title-form'){e.preventDefault();if(busy)return;const id=new FormData(e.target).get('title');busy=true;try{if(online){const result=await request('/api/action',{action:'title',id});s=result.state;online=result.user;}else if(!progressionAction(s,{action:'title',id}))throw new Error('Danh hiệu chưa mở.');notice='Đã lưu danh hiệu.';}catch(err){notice=err.message;}finally{busy=false;render();}return;}if(e.target.classList.contains('world-form')){e.preventDefault();if(busy)return;if(!online){notice='Cần đăng nhập.';render();return;}const form=new FormData(e.target),payload={action:e.target.dataset.kind,id:e.target.dataset.id||form.get('id')};for(const key of ['text','amount','price'])if(form.has(key))payload[key]=key==='text'?form.get(key):Number(form.get(key));if(payload.action==='chat'){payload.channel=chatMode;payload.replyId=replyId;payload.item=form.get('item')||'';if(!payload.text?.trim()&&!payload.item){notice='Nhập tin nhắn hoặc chọn trang bị để chia sẻ.';render();return;}}busy=true;try{const result=await request('/api/action',payload);s=result.state;online=result.user;if(payload.action==='chat'){chatDrafts[chatMode]='';replyId=null;attached=false;attachedGear='';notice='Đã gửi tin nhắn.';}else if(payload.action==='mail-send'){mailDraft='';notice='Đã gửi thư.';}else notice=s.log[0];await refreshWorld();}catch(err){notice=err.message;}finally{busy=false;render();}return;}if(e.target.id==='finance-form'){e.preventDefault();if(busy)return;const form=new FormData(e.target),amount=Number(form.get('amount')),direction=e.submitter?.value,kind=e.target.dataset.kind;financeAmount=Number.isFinite(amount)?amount:1;busy=true;try{if(online){const result=await request('/api/action',{action:kind,amount,direction});s=result.state;online=result.user;notice=s.log[0];}else{const ok=(kind==='bank'?bankTransfer:exchange)(s,direction,amount);notice=ok?s.log[0]:'Không đủ số dư hoặc số lượng không hợp lệ.';}}catch(err){notice=err.message;}finally{busy=false;render();}return;}if(e.target.classList.contains('module-form')){e.preventDefault();if(busy)return;const slot=Number(e.target.dataset.slot),moduleId=new FormData(e.target).get('module');busy=true;try{if(online){const result=await request('/api/action',{action:'module',id:selectedGear,slot,module:moduleId});s=result.state;online=result.user;notice='Đã lắp module.';}else notice=installModule(s,selectedGear,slot,moduleId)?'Đã lắp module.':'Không thể lắp: kiểm tra credits, cấp độ hoặc module đã trùng.';}catch(err){notice=err.message;}finally{busy=false;render();}return;}if(!['name-form','auth-form'].includes(e.target.id))return;e.preventDefault();if(busy)return;const form=new FormData(e.target);busy=true;try{if(e.target.id==='auth-form'){const result=await request('/api/'+(e.submitter?.value||'login'),{username:form.get('username'),password:form.get('password')});online=result.user;s=result.state;uiBoot=false;profileSection='profile';chatDrafts={};mailDraft='';mailRecipient='';replyId=null;chatMode='global';tab='hub';await Promise.all([refreshPlayers(),refreshWorld()]);}else{const name=form.get('runner').trim().slice(0,24);if(name){if(online){const result=await request('/api/action',{action:'name',id:name});s=result.state;online=result.user;}else s.name=name;}}notice='';}catch(err){notice=err.message;}finally{busy=false;render();}});
try{const result=await request('/api/me');online=result.user;s=result.state;await refreshPlayers();}catch{}
render();

try{await refreshWorld();}catch{}
render();
setInterval(async()=>{if(document.hidden||busy)return;try{await refreshWorld();if(tab==='market'&&JSON.stringify(world.market)!==marketRendered&&!document.activeElement?.closest('input,select,textarea'))render();if(online){const me=await request('/api/me');if(JSON.stringify(me.state)!==JSON.stringify(s)){if((me.state.notificationSeq||0)>(s.notificationSeq||0))sounds.play('notice');s=me.state;online=me.user;if(!document.activeElement?.closest('input,select,textarea'))render();}}const latest=world.messages.at(-1),ticker=document.querySelector('.chat-ticker');if(ticker)ticker.textContent=latest?`${latest.name}: ${latest.text}`:'Kênh toàn cầu / Chưa có tin nhắn';const feed=document.querySelector('.chat-feed');if(feed){const atBottom=feed.scrollHeight-feed.clientHeight-feed.scrollTop<30,position=feed.scrollTop;feed.innerHTML=chatFeed(world,esc,chatMode,settings(s));feed.scrollTop=atBottom?feed.scrollHeight:position;}const mail=document.querySelector('.mail-list');if(mail)mail.innerHTML=mailFeed(world,online,esc,button);const nav=document.querySelector('.bottom-nav [data-id="chat"]');nav?.querySelector('i')?.remove();if(latest&&latest.time>lastSeenChat||(world.guildMessages.at(-1)?.time||0)>lastSeenGuild||world.mail.some(m=>m.recipient===online?.id&&!m.read)||s.notifications?.some(n=>!n.read))nav?.insertAdjacentHTML('beforeend','<i></i>');}catch{}},5000);

function sizeChat(){const screen=document.querySelector('.comms-screen.chat-mode'),nav=document.querySelector('.bottom-nav');if(!screen||!nav)return;if(innerWidth<=680){screen.style.minHeight='0';screen.style.height=Math.max(180,nav.getBoundingClientRect().top-screen.getBoundingClientRect().top-8)+'px';}else{screen.style.height='';screen.style.minHeight='';}}
window.addEventListener('resize',sizeChat);

setInterval(()=>{if(!s.work)return;const remaining=workRemaining(s);document.querySelectorAll('[data-work-clock]').forEach(el=>el.textContent=remaining?'Còn '+duration(remaining):'Hoàn thành · có thể nhận thưởng');document.querySelectorAll('[data-action="work-claim"]').forEach(el=>el.disabled=busy||remaining>0);document.querySelectorAll('[data-work-bar]').forEach(el=>el.style.width=Math.min(100,(Date.now()-s.work.startedAt)/(s.work.endsAt-s.work.startedAt)*100)+'%');},1000);

function introCards(){const p=settings(s);return `${!p.disableTutorial&&!s.tutorialDismissed&&s.level===1?`<article class="intro-card"><b>CHÀO MỪNG, RUNNER</b><p>Nhận hợp đồng trước khi khám phá. Máy in và trạm nghỉ giúp bạn chuẩn bị cho chuyến đi.</p>${button('Xem hướng dẫn','nav','codex')}${button('Đã hiểu','tutorial-dismiss')}</article>`:''}${!p.hideUpdates&&s.seenUpdateVersion!==appVersion?`<article class="intro-card"><b>CYPER // ZERO · v${appVersion}</b><p>Cài đặt giao diện, âm thanh, quyền riêng tư và kết quả chiến đấu đã sẵn sàng.</p>${button('Đã đọc','updates-dismiss')}${button('Cài đặt','settings-open')}</article>`:''}`;}
function modalView(){if(pendingDelete)return `<div class="modal-overlay"><section role="dialog" aria-modal="true" aria-labelledby="delete-title"><h2 id="delete-title">XÓA VĨNH VIỄN TÀI KHOẢN?</h2><p>Nhân vật ${esc(pendingDelete.confirmName)}, tài sản, tin rao và thư sẽ bị xóa. Thao tác không thể khôi phục.</p><div class="actions">${button('Giữ tài khoản','delete-cancel')}${button('Xác nhận xóa vĩnh viễn','delete-confirm')}</div></section></div>`;if(victoryModal)return `<div class="modal-overlay"><section class="victory-screen" role="dialog" aria-modal="true" aria-labelledby="victory-title"><small>${victoryModal.pvp?'PVP':'PVE'} / THẮNG TRẬN</small><h2 id="victory-title">TÍN HIỆU SỐNG SÓT</h2><p>${esc(victoryModal.name)}</p><strong>+${victoryModal.xp} XP · +${victoryModal.credits} ₡</strong><p>Phần thưởng đã được cộng vào nhân vật.</p>${button('Tiếp tục','victory-close')}</section></div>`;return '';}
async function submitSettings(e){if(busy)return;if(e.target.id==='delete-form'){const f=new FormData(e.target),name=f.get('confirmName'),password=f.get('password');if(!online||name!==s.name||password.length<8||password.length>128){notice='Nhập đúng bí danh hiện tại và mật khẩu.';render();return;}pendingDelete={confirmName:name,password};render();return;}busy=true;try{const values={...settingsDraft};if(online){const result=await request('/api/action',{action:'settings',values});s=result.state;online=result.user;}else if(!settingsAction(s,{action:'settings',values}))throw new Error('Cài đặt không hợp lệ.');settingsDraft={...settings(s)};notice=settings(s).language==='en'?'Settings saved.':'Đã áp dụng và lưu cài đặt.';}catch(error){notice=error.message;}finally{busy=false;render();}}
async function confirmDeletion(){if(!online||!pendingDelete||busy)return;busy=true;try{await request('/api/account/delete',{...pendingDelete,confirm:true});pendingDelete=null;online=null;uiBoot=false;s=fresh();try{const saved=JSON.parse(localStorage.getItem('cyper-save'));if(saved?.version===1)s=saved;}catch{}settingsDraft=null;tab='account';profileSection='auth';chatDrafts={};mailDraft='';replyId=null;clientNotice='';await Promise.all([refreshWorld(),refreshPlayers()]);notice='Tài khoản online đã được xóa. Nhân vật khách trên thiết bị được giữ lại.';}catch(error){pendingDelete=null;notice=error.message;}finally{busy=false;render();}}
function notifyClient(kind,message){clientNotice=message;sounds.play(kind);if(document.hidden&&'Notification' in window&&Notification.permission==='granted')try{new Notification('CYPER // ZERO',{body:message,tag:'cyper-'+kind});}catch{}const banner=document.querySelector('.client-notice');if(banner){banner.hidden=false;banner.querySelector('span').textContent=message;}}
function watchWorld(previous,next){if(!previous||!online)return;const p=settings(s),oldIds=new Set(previous.messages.map(m=>m.id)),oldMail=new Set(previous.mail.map(m=>m.id));if(next.messages.some(m=>!oldIds.has(m.id)&&m.author!==online.id&&(m.text||'').includes('@'+s.name)))notifyClient('mention','Có tin mới nhắc đến @'+s.name);if(next.mail.some(m=>!oldMail.has(m.id)&&m.recipient===online.id))notifyClient('mail','Bạn có thư mới.');if(p.notifyGuild&&previous.corporation===next.corporation&&next.guildMessages.some(m=>!previous.guildMessages.some(old=>old.id===m.id)&&m.author!==online.id))notifyClient('notice','Kênh tập đoàn có tin mới.');if(p.notifyWorld&&next.funds.some(f=>f.active&&!previous.funds.find(old=>old.id===f.id)?.active))notifyClient('notice','Buff cộng đồng vừa được kích hoạt.');}
document.addEventListener('pointerdown',()=>{sounds.unlock();},{passive:true});document.addEventListener('keydown',()=>{sounds.unlock();});document.addEventListener('visibilitychange',()=>{if(document.hidden)sounds.pause();else sounds.resume();});window.addEventListener('pagehide',()=>sounds.dispose());
